package studio.jiayu.neoagent;
import android.content.Context;import org.json.*;import java.util.*;
/** A bounded ordered plan. Stage transitions are journaled before launching the next app. */
final class TaskWorkflow {
 final ArrayList<TaskSpec> steps=new ArrayList<>();final String original;int index,baseSteps=24;
 TaskWorkflow(Context c,JSONObject plan,String user)throws Exception{this(c,plan,user,false);}
 private TaskWorkflow(Context c,JSONObject plan,String user,boolean restoring)throws Exception{original=user;JSONArray entries=plan.optJSONArray("tasks");if(entries==null)entries=new JSONArray().put(plan);if(entries.length()<1||entries.length()>6)throw new Exception("一次支持1至6个任务，请分批发送");if(!restoring)entries=normalize(c,entries,user);List<StageSourceRules.AppSpan> spans=AppTaskScope.spans(c,user);boolean sourced=false;ArrayList<String> packages=new ArrayList<>();ArrayList<StageSourceRules.Clause> sources=new ArrayList<>();for(int i=0;i<entries.length();i++){TaskSpec item=new TaskSpec(c,entries.getJSONObject(i),user,spans);steps.add(item);packages.add(item.pkg);sources.add(item.sourceClause);sourced|=item.sourceClause!=null;}
  SharedAppSourceRules.Group shared=SharedAppSourceRules.detect(user,spans);if(shared!=null){if(packages.size()!=shared.members.size())throw new WorkflowPlanException("source_order");for(int i=0;i<packages.size();i++)if(!packages.get(i).equals(shared.members.get(i).pkg))throw new WorkflowPlanException("source_order");}
  if(sourced)StageSourceRules.ordered(spans,packages,sources);
  List<PlanCoverage.Mention> mentions=AppTaskScope.mentions(c,user);ArrayList<String> identities=new ArrayList<>();for(PlanCoverage.Mention mention:mentions)identities.add(Conversation.resolve(c,mention.app));ArrayList<PlanCoverage.Stage> stages=new ArrayList<>();for(TaskSpec item:steps)stages.add(new PlanCoverage.Stage(item.pkg,item.goal));String issue=PlanCoverage.issue(user,mentions,identities,stages);if(!issue.isEmpty())throw new Exception(issue);
 }
 private static JSONArray normalize(Context c,JSONArray input,String user)throws Exception{JSONObject shared=SharedComparisonPlan.create(c,user);if(shared!=null)return shared.getJSONArray("tasks");JSONArray result=new JSONArray();for(int i=0;i<input.length();i++){
  JSONObject next=input.getJSONObject(i);if(result.length()>0){JSONObject previous=result.getJSONObject(result.length()-1);String pkg=Conversation.resolve(c,previous.getString("app"));if(pkg.equals("cn.wps.moffice_eng")&&pkg.equals(Conversation.resolve(c,next.getString("app")))&&PlanCoverage.documentContinuation(user,previous.getString("goal"),next.getString("goal"))){
    JSONObject merged=new JSONObject(previous.toString());String source=AppTaskScope.mergeSources(c,pkg,user,TaskSpec.readSource(previous),TaskSpec.readSource(next));if(!source.isEmpty())merged.put("source",source);merged.put("goal","同一份本轮新建文件的连续流程，按顺序全部完成后结束：\n"+previous.getString("goal").replace("停止条件", "阶段完成条件")+"\n完成前一阶段的保存和重新打开核对后，继续：\n"+next.getString("goal"));result.put(result.length()-1,merged);continue;
   }}result.put(new JSONObject(next.toString()));}return result;}
 TaskSpec current(){return steps.get(index);}
 Collection<String> packages(){LinkedHashSet<String> r=new LinkedHashSet<>();for(TaskSpec s:steps)r.add(s.pkg);return r;}
 String apps(){ArrayList<String> names=new ArrayList<>();for(TaskSpec s:steps)if(!names.contains(s.app))names.add(s.app);return String.join("、",names);}
 String brief(){StringBuilder b=new StringBuilder();for(int i=0;i<steps.size();i++){TaskSpec t=steps.get(i);b.append(i+1).append(". ").append(t.app).append("：").append(t.goal.substring(0,Math.min(100,t.goal.length()))).append(t.goal.length()>100?"…":"").append('\n');}return b.toString().trim();}
 String description(){StringBuilder b=new StringBuilder();for(int i=0;i<steps.size();i++)b.append(i+1).append(". ").append(steps.get(i).app).append("：").append(steps.get(i).goal).append('\n');return b.toString().trim();}
 JSONArray list()throws Exception{JSONArray a=new JSONArray();for(TaskSpec s:steps)a.put(s.json());return a;}
 JSONObject json()throws Exception{return new JSONObject().put("version",1).put("original",original).put("index",index).put("baseSteps",baseSteps).put("tasks",list());}
 static TaskWorkflow restore(Context c,JSONObject o)throws Exception{if(o.getInt("version")!=1)throw new Exception("Invalid workflow version");TaskWorkflow w=new TaskWorkflow(c,o,o.getString("original"),true);w.index=o.getInt("index");w.baseSteps=o.getInt("baseSteps");if(w.index<0||w.index>=w.steps.size()||w.baseSteps<1||w.baseSteps>40)throw new Exception("Invalid workflow position");JSONArray a=o.getJSONArray("tasks");for(int i=0;i<a.length();i++){TaskSpec t=w.steps.get(i);JSONObject old=a.getJSONObject(i);if(!t.pkg.equals(old.getString("package"))||t.checkout!=old.getBoolean("checkout"))throw new Exception("任务应用或范围已改变");t.state=old.getString("state");if(i<w.index&&!t.state.equals("verified")&&!t.state.equals("reported")&&!t.state.equals("partial"))throw new Exception("Invalid completed stage");if(i>=w.index&&!t.state.equals("pending")&&!t.state.equals("running")&&!t.state.equals("paused"))throw new Exception("Invalid remaining stage");t.verified=old.optBoolean("verified");t.result=old.optString("result");t.proof=old.optJSONObject("proof")==null?new JSONObject():old.getJSONObject("proof");if(t.state.equals("partial")&&(!t.checkout||!MovieBoundaryStop.allowed(t.pkg,t.original)||!t.proof.optString("kind").equals("allowed_movie_boundary")||!PurchaseFacts.digest(t.original).equals(t.proof.optString("original_signature"))||!t.proof.optBoolean("native_stop_verified")||t.proof.optBoolean("full_order_review_verified")||t.verified))throw new Exception("Invalid boundary-stop evidence");}w.current().state="paused";return w;}
 String results(){StringBuilder b=new StringBuilder();for(int i=0;i<steps.size();i++){TaskSpec t=steps.get(i);String label=t.state.equals("verified")?"已核验":t.state.equals("reported")?"模型报告完成，待核实":t.state.equals("partial")?"按限制停下（订单核对未完成）":t.state.equals("stopped")?"已结束":t.state.equals("cancelled")?"未执行":t.state.equals("paused")?"已暂停":t.state.equals("running")?"执行中":"待执行";b.append(i+1).append(". ").append(t.app).append(" · ").append(label);if(!t.result.isEmpty())b.append("：").append(t.result);b.append('\n');}return b.toString().trim();}
 void stopped(){current().state="stopped";for(int i=index+1;i<steps.size();i++)steps.get(i).state="cancelled";}
}
